public class FeeBench {
    // Phí 1,5%, làm tròn HALF_UP tới đồng
    static long feeBigDecimal(long amount) {
        return BigDecimal.valueOf(amount).multiply(new BigDecimal("0.015"))
                .setScale(0, RoundingMode.HALF_UP).longValueExact();
    }

    static long feeLong(long amount) {
        return (amount * 15 + 500) / 1000;
    }

    public static void main(String[] args) {
        int n = 10_000_000;
        long t0 = System.nanoTime();
        for (int i = 0; i < n; i++) feeBigDecimal(100_000 + i);
        long t1 = System.nanoTime();
        for (int i = 0; i < n; i++) feeLong(100_000 + i);
        long t2 = System.nanoTime();
        System.out.printf("BigDecimal: %d ms%n", (t1 - t0) / 1_000_000);
        System.out.printf("long:       %d ms%n", (t2 - t1) / 1_000_000);
    }
}

