@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.NANOSECONDS)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 1)
@Fork(2)
@State(Scope.Thread)
public class FeeBenchmark {
    long amount = 1_250_000;   // field của @State: JIT không coi là hằng số

    @Benchmark public long bigDecimal() { return FeeBench.feeBigDecimal(amount); }
    @Benchmark public long longMath()   { return FeeBench.feeLong(amount); }    // trả về: JMH đưa vào Blackhole
    @Benchmark public void longDiscarded() { FeeBench.feeLong(amount); }     // cố tình bỏ kết quả
    @Benchmark public void baseline() { }
}

